import * as React from "react";
import { View, StyleSheet, Image } from "react-native";
import { Tag } from "./Tag";
import { DateDisplay } from "./DateDisplay";
import { JobDetails } from "./JobDetails";
import { ApplicationDeadline } from "./ApplicationDeadline";
import { ApplyButton } from "./ApplyButton";

export function JobCard() {
  const tags = ["tag", "tag"];
  
  return (
    <View style={styles.cardContainer}>
      <Image
        resizeMode="cover"
        fitContent
        source={{ uri: "https://cdn.builder.io/api/v1/image/assets/TEMP/1af1f6062bc37bdfa7a65506ca1347b1305f313cfe16d32b7f1817693ecf420f?placeholderIfAbsent=true&apiKey=6d0c12d1b41b41cabcfc21945748b772" }}
        style={styles.cardBackground}
      >
        <View style={styles.bookmarkContainer}>
          <Image
            resizeMode="contain"
            source={{ uri: "https://cdn.builder.io/api/v1/image/assets/TEMP/290b46e8f97095809844b99b9262c3411dec2c4940a2e8b50dc2a766a4b0e073?placeholderIfAbsent=true&apiKey=6d0c12d1b41b41cabcfc21945748b772" }}
            style={styles.bookmarkIcon}
          />
        </View>
      </Image>
      
      <View style={styles.contentContainer}>
        <View style={styles.headerSection}>
          <View style={styles.tagsContainer}>
            <View style={styles.tagRow}>
              {tags.map((tag, index) => (
                <Tag key={index} label={tag} />
              ))}
            </View>
            <DateDisplay date="Date" />
          </View>
          
          <JobDetails
            title="TITLE"
            description="Lorem ipsum dolor sit amet consectetur. Egestas velit ornare cursus suspendisse vitae ac vel"
          />
        </View>
        
        <View style={styles.footerSection}>
          <View style={styles.divider} />
          <ApplicationDeadline date="00.00.0000" />
          <ApplyButton />
        </View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  cardContainer: {
    justifyContent: "center",
    alignItems: "stretch",
    borderTopLeftRadius: 16,
    borderTopRightRadius: 16,
    borderBottomRightRadius: 0,
    borderBottomLeftRadius: 0,
    borderWidth: 1,
    borderColor: "#D8D8D8",
    display: "flex",
    maxWidth: 328,
    flexDirection: "column",
    overflow: "hidden",
  },
  cardBackground: {
    position: "relative",
    display: "flex",
    aspectRatio: "1.92",
    minHeight: 171,
    width: "100%",
    padding: 16,
    paddingBottom: 119,
    overflow: "hidden",
    justifyContent: "center",
  },
  bookmarkContainer: {
    justifyContent: "center",
    alignItems: "center",
    borderRadius: 100,
    backgroundColor: "#F6F8FF",
    position: "relative",
    display: "flex",
    width: 36,
    padding: 8,
    overflow: "hidden",
    height: 36,
  },
  bookmarkIcon: {
    alignSelf: "stretch",
    position: "relative",
    display: "flex",
    marginVertical: "auto",
    width: 20,
    aspectRatio: 1,
  },
  contentContainer: {
    display: "flex",
    width: "100%",
    padding: 16,
    flexDirection: "column",
    alignItems: "stretch",
    fontFamily: "Roboto, sans-serif",
    justifyContent: "space-between",
    flex: 1,
  },
  headerSection: {
    display: "flex",
    width: "100%",
    flexDirection: "column",
    alignItems: "stretch",
  },
  tagsContainer: {
    display: "flex",
    width: "100%",
    flexDirection: "column",
    alignItems: "stretch",
    fontSize: 12,
    fontWeight: "400",
  },
  tagRow: {
    display: "flex",
    width: "100%",
    alignItems: "center",
    flexDirection: "row",
    gap: 8,
  },
  footerSection: {
    display: "flex",
    marginTop: 44,
    width: "100%",
    flexDirection: "column",
    alignItems: "stretch",
    fontSize: 16,
  },
  divider: {
    backgroundColor: "#D8D8D8",
    height: 1,
    width: "100%",
  },
});
